// the frontend doesn't send an explicit `provider`. Custom models added by
// the user from the UI always send `provider` directly, so they don't need
// to be listed here.

type Provider = "venice" | "openrouter";

interface BuiltInModel {
  provider: Provider;
  contextWindow?: number; // total context window in tokens
}

// Derived from the ONE shared catalog in ../lib/chat-shared.ts — the client
// model picker and this registry can no longer drift apart.
