interface RequestBody {
  messages?: Array<{
    role: "system" | "user" | "assistant";
    content: string;
  }>;
  model?: string;
  // Frontend always sends `provider` so user-defined custom models can route
  // without us needing to register them server-side.
  provider?: Provider;
  // Supabase access token rides in the body (NOT the Authorization header)
  // because zo's public edge proxy strips Authorization before it reaches us.
  accessToken?: string;
  // Current chat/session id — lets the server look up whether this thread is
  // a declared being and activate its memory limbs. Optional: absent = no limbs.
  threadId?: string;
}

// Defensive: zo's secrets UI sometimes stores values with surrounding quotes
// (the user can paste "sk-..." and the quotes get treated as part of the
// value). Trim them off + whitespace so the Bearer header is clean.
function cleanKey(raw: string | undefined): string | undefined {
  if (!raw) return undefined;
  let v = raw.trim();
  if (
    (v.startsWith('"') && v.endsWith('"')) ||
    (v.startsWith("'") && v.endsWith("'"))
  ) {
    v = v.slice(1, -1).trim();
  }
  return v;
}

function endpointFor(provider: Provider): {
  url: string;
  key: string | undefined;
  keyName: string;
} {
  if (provider === "venice") {
    return {
      url: "https://api.venice.ai/api/v1/chat/completions",
      key: cleanKey(process.env.VENICE_AI),
      keyName: "VENICE_AI",
    };
  }
  return {
    url: "https://openrouter.ai/api/v1/chat/completions",
    key: cleanKey(process.env.OPENROUTER_API_KEY),
    keyName: "OPENROUTER_API_KEY",
  };
}

// Same envelope shape on error and success so the frontend can always render
// the assistant's bubble. Friendly errors are surfaced as bubble text instead
